-- 0050_simplify_payment_accounts.sql
-- Simplifies payment accounts to exactly two primary accounts: Cash in Hand and Bank Account.
-- Adds explicit account classification, renames default bank accounts to 'Bank Account',
-- and safely retires unused autogenerated UPI accounts (code 1030).

-- 1. Add account classification columns
ALTER TABLE accounting_financial_accounts
ADD COLUMN IF NOT EXISTS is_payment_account BOOLEAN NOT NULL DEFAULT FALSE,
ADD COLUMN IF NOT EXISTS account_role TEXT NOT NULL DEFAULT 'INTERNAL_LEDGER';

-- 2. Classify Cash accounts (Code 1010 or subtype CASH) as primary cash payment accounts
UPDATE accounting_financial_accounts
SET is_payment_account = true,
    account_role = 'CASH',
    name = CASE WHEN name = 'Cash on Hand' THEN 'Cash in Hand' ELSE name END
WHERE code = '1010' OR (type = 'ASSET' AND subtype = 'CASH');

-- 3. Classify Bank accounts (Code 1020 or subtype BANK) as primary bank payment accounts
-- Rename default system bank accounts to canonical 'Bank Account'
UPDATE accounting_financial_accounts
SET is_payment_account = true,
    account_role = 'BANK',
    name = 'Bank Account'
WHERE code = '1020' OR (type = 'ASSET' AND subtype = 'BANK' AND is_system = true);

-- 4. Safely retire unused autogenerated UPI accounts (code 1030) that have no activity or dependencies
UPDATE accounting_financial_accounts fa
SET is_active = false,
    is_payment_account = false,
    account_role = 'RETIRED_SYSTEM',
    updated_at = NOW()
WHERE fa.code = '1030'
  AND fa.opening_balance_minor = 0
  AND fa.current_balance_minor = 0
  AND NOT EXISTS (
    SELECT 1 FROM accounting_journal_lines jl WHERE jl.financial_account_id = fa.id
  )
  AND NOT EXISTS (
    SELECT 1 FROM accounting_transactions t WHERE t.financial_account_id = fa.id OR t.destination_account_id = fa.id
  )
  AND NOT EXISTS (
    SELECT 1 FROM accounting_payments p WHERE p.financial_account_id = fa.id
  );

-- 5. If any active account 1030 has a non-zero balance or history (e.g. demo workspace),
-- classify as LEGACY_PAYMENT so balances and audit trails are preserved without silent loss.
UPDATE accounting_financial_accounts
SET account_role = 'LEGACY_PAYMENT',
    is_payment_account = false
WHERE code = '1030' AND is_active = true;

-- 6. Index for fast querying of payment accounts per workspace
CREATE INDEX IF NOT EXISTS idx_acc_fin_accounts_payment
ON accounting_financial_accounts(workspace_id, is_payment_account, is_active);
